import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Catalog Attributes — Datagrid Listing (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attributes-list","title":"List Catalog Attributes (Datagrid)","description":"Cursor-paginated query returning the flat attribute list — the GraphQL equivalent of the admin Catalog → Attributes datagrid. Supports filtering by code, type, admin_name, boolean flags, and locale.","query":"query AdminCatalogAttributes(\\n  $first: Int\\n  $after: String\\n  $type: String\\n  $isConfigurable: Int\\n  $locale: String\\n) {\\n  adminAttributes(\\n    first: $first\\n    after: $after\\n    type: $type\\n    isConfigurable: $isConfigurable\\n    locale: $locale\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        code\\n        type\\n        adminName\\n        isRequired\\n        isUnique\\n        valuePerLocale\\n        valuePerChannel\\n        isFilterable\\n        isConfigurable\\n        isVisibleOnFront\\n        isUserDefined\\n        swatchType\\n        position\\n        locale\\n        createdAt\\n        updatedAt\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      endCursor\\n      startCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"type\\": \\"select\\",\\n  \\"isConfigurable\\": 1,\\n  \\"locale\\": \\"en\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminAttributes\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/attributes/12\\",\\n            \\"_id\\": 12,\\n            \\"code\\": \\"color\\",\\n            \\"type\\": \\"select\\",\\n            \\"adminName\\": \\"Color\\",\\n            \\"isRequired\\": 0,\\n            \\"isUnique\\": 0,\\n            \\"valuePerLocale\\": 0,\\n            \\"valuePerChannel\\": 0,\\n            \\"isFilterable\\": 1,\\n            \\"isConfigurable\\": 1,\\n            \\"isVisibleOnFront\\": 1,\\n            \\"isUserDefined\\": 1,\\n            \\"swatchType\\": \\"color\\",\\n            \\"position\\": 5,\\n            \\"locale\\": \\"en\\",\\n            \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n            \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false,\\n        \\"endCursor\\": \\"MA==\\",\\n        \\"startCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attributes-listing.md","filePath":"api/graphql-api/admin/catalog/attributes/attributes-listing.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/catalog/attributes/attributes-listing.md"};function c(i,t,n,s,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attributes-—-datagrid-listing-graphql" tabindex="-1">Catalog Attributes — Datagrid Listing (GraphQL) <a class="header-anchor" href="#catalog-attributes-—-datagrid-listing-graphql" aria-label="Permalink to &quot;Catalog Attributes — Datagrid Listing (GraphQL)&quot;">​</a></h1><p>Cursor-paginated GraphQL query that mirrors the Bagisto admin <strong>Catalog → Attributes</strong> datagrid. Returns the flat attribute list with filtering, sorting, and cursor pagination.</p><p>For attribute types, options, and the configurable and filterable flags, see the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes overview</a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Pagination</th></tr></thead><tbody><tr><td><code>adminAttributes</code></td><td>Query</td><td>Cursor (<code>first</code> / <code>after</code>)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>Number of items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.endCursor</code> for keyset pagination</td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>last</code></td><td><code>Int</code></td><td>Page size when paging backwards</td><td><code>10</code></td></tr><tr><td><code>before</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.startCursor</code></td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>id</code></td><td><code>String</code></td><td>Filter by attribute ID — single integer or comma-separated list (e.g. <code>&quot;1&quot;</code> or <code>&quot;1,2&quot;</code>)</td><td><code>&quot;12&quot;</code></td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Partial attribute code match (SQL <code>LIKE %value%</code>)</td><td><code>&quot;color&quot;</code></td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>Exact attribute type filter</td><td><code>&quot;select&quot;</code></td></tr><tr><td><code>admin_name</code></td><td><code>String</code></td><td>Partial admin name match (SQL <code>LIKE %value%</code>)</td><td><code>&quot;Color&quot;</code></td></tr><tr><td><code>is_required</code></td><td><code>Int</code></td><td>Filter by is_required: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_unique</code></td><td><code>Int</code></td><td>Filter by is_unique: <code>0</code> = no, <code>1</code> = yes</td><td><code>0</code></td></tr><tr><td><code>is_filterable</code></td><td><code>Int</code></td><td>Filter by is_filterable: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_configurable</code></td><td><code>Int</code></td><td>Filter by is_configurable: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_visible_on_front</code></td><td><code>Int</code></td><td>Filter by is_visible_on_front: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_user_defined</code></td><td><code>Int</code></td><td>Filter by is_user_defined: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code for translation resolution (default: app locale)</td><td><code>&quot;en&quot;</code></td></tr><tr><td><code>sort</code></td><td><code>String</code></td><td>Column to sort by (see Sorting section below)</td><td><code>&quot;id&quot;</code></td></tr><tr><td><code>order</code></td><td><code>String</code></td><td>Sort direction: <code>&quot;asc&quot;</code> or <code>&quot;desc&quot;</code> (default <code>&quot;desc&quot;</code>)</td><td><code>&quot;desc&quot;</code></td></tr></tbody></table><p>Every filter is a first-class GraphQL argument — pass them alongside <code>first</code> and <code>after</code>, not inside a nested filter object. Filters combine with AND, so each one narrows the result. Most filter names are snake_case (<code>admin_name</code>, <code>is_required</code>) while the node fields they filter are camelCase (<code>adminName</code>, <code>isRequired</code>); that mismatch is the literal schema.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><p>Each <code>edges[].node</code> object contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/attributes/12</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw attribute ID</td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Attribute code (e.g. <code>color</code>, <code>size</code>)</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>Attribute type (e.g. <code>select</code>, <code>text</code>, <code>boolean</code>)</td></tr><tr><td><code>adminName</code></td><td><code>String</code></td><td>Internal admin-facing label</td></tr><tr><td><code>isRequired</code></td><td><code>Int</code></td><td><code>1</code> = required on product forms</td></tr><tr><td><code>isUnique</code></td><td><code>Int</code></td><td><code>1</code> = value must be unique across products</td></tr><tr><td><code>valuePerLocale</code></td><td><code>Int</code></td><td><code>1</code> = separate value per store locale</td></tr><tr><td><code>valuePerChannel</code></td><td><code>Int</code></td><td><code>1</code> = separate value per channel</td></tr><tr><td><code>isFilterable</code></td><td><code>Int</code></td><td><code>1</code> = appears in layered navigation</td></tr><tr><td><code>isConfigurable</code></td><td><code>Int</code></td><td><code>1</code> = used as a configurable variant axis</td></tr><tr><td><code>isVisibleOnFront</code></td><td><code>Int</code></td><td><code>1</code> = shown on the storefront product page</td></tr><tr><td><code>isUserDefined</code></td><td><code>Int</code></td><td><code>1</code> = admin-created (not a system attribute)</td></tr><tr><td><code>swatchType</code></td><td><code>String</code></td><td>Swatch mode (<code>color</code>, <code>image</code>, <code>text</code>); <code>null</code> for non-swatch types</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Display order position</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code used for name resolution</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>ISO 8601 last-update timestamp</td></tr></tbody></table><h2 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h2><p><code>translations</code>, <code>options</code>, <code>validation</code>, <code>defaultValue</code>, <code>isComparable</code>, <code>enableWysiwyg</code>, and <code>regex</code> are declared on the type but resolve only on the item query <a href="/api/graphql-api/admin/catalog/attributes/attributes-detail.html"><code>adminAttribute(id:)</code></a>. Selecting them here is not an error — you simply get <code>null</code>.</p><p><code>swatchType</code> and <code>position</code> are also frequently <code>null</code> on the listing, but for a different reason: they are genuinely unset on most attributes rather than withheld.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Pass <code>sort</code> with the column name and <code>order</code> for direction.</p><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Attribute ID (default)</td></tr><tr><td><code>code</code></td><td>Attribute code</td></tr><tr><td><code>admin_name</code></td><td>Admin label</td></tr><tr><td><code>type</code></td><td>Attribute type</td></tr><tr><td><code>position</code></td><td>Display order position</td></tr></tbody></table><h2 id="cursor-pagination" tabindex="-1">Cursor Pagination <a class="header-anchor" href="#cursor-pagination" aria-label="Permalink to &quot;Cursor Pagination&quot;">​</a></h2><ul><li><code>first</code> controls the page size (default <code>10</code>, max <code>50</code>).</li><li>To fetch the next page, pass the <code>pageInfo.endCursor</code> value as <code>after</code> in the next request.</li><li><code>totalCount</code> reflects the full count of matching attributes across all pages.</li></ul><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>The boolean flags are integers, not booleans.</strong> <code>isRequired</code>, <code>isUnique</code>, <code>isFilterable</code>, <code>isConfigurable</code>, <code>isVisibleOnFront</code>, <code>isUserDefined</code>, <code>valuePerLocale</code>, and <code>valuePerChannel</code> all come back as <code>0</code> or <code>1</code>. Note <code>0</code> is falsy in JavaScript but <code>&quot;0&quot;</code> would not be — these are real <code>Int</code>s here, unlike the product listing where the same concepts are strings.</li><li><strong>System attributes are included.</strong> The listing returns both Bagisto&#39;s built-in attributes and admin-created ones. Pass <code>is_user_defined: 1</code> for admin-created only — useful because system attributes cannot be deleted.</li><li><strong><code>swatchType</code> is only meaningful for swatch-capable types.</strong> It stays <code>null</code> on a plain <code>text</code> or <code>select</code> attribute rather than carrying a default.</li><li><strong>REST returns the same rows</strong> through <code>GET /api/admin/catalog/attributes</code>, with identical filter and sort semantics.</li></ul>',22)]))}const p=e(r,[["render",c]]);export{g as __pageData,p as default};
